  (55, 'UUD 1945', '1945', 1945, 'Undang-Undang Dasar Negara Republik Indonesia Tahun 1945', 'berlaku', 'Perubahan Pertama (1999), Kedua (2000), Ketiga (2001), Keempat (2002)', '{}', 'Nasional', 'Otonomi Daerah', 'https://peraturan.bpk.go.id/Details/101646/uud-no--', 'normal', '2026-08-17 13:48:43', '2026-08-18 13:46:26'),
  (56, 'UU', '23', 2014, 'Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah', 'berlaku', 'dicabut sebagian dengan: 2 peraturan; diubah dengan: 6 peraturan; mencabut: 4 peraturan; mengubah: 2 peraturan', '{\"mencabut\": [{\"url\": \"https://peraturan.bpk.go.id/Details/39043/uu-no-12-tahun-2008\", \"judul\": \"UU No. 12 Tahun 2008 tentang Perubahan Kedua atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah\", \"label\": \"UU No. 12 Tahun 2008\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/40250/uu-no-8-tahun-2005\", \"judul\": \"UU No. 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan atas Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah Menjadi Undang-Undang\", \"label\": \"UU No. 8 Tahun 2005\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/40768/uu-no-32-tahun-2004\", \"judul\": \"UU No. 32 Tahun 2004 tentang Pemerintahan Daerah\", \"label\": \"UU No. 32 Tahun 2004\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/50675/uu-no-5-tahun-1962\", \"judul\": \"UU No. 5 Tahun 1962 tentang Perusahaan Daerah\", \"label\": \"UU No. 5 Tahun 1962\"}], \"mengubah\": [{\"url\": \"https://peraturan.bpk.go.id/Details/38643/uu-no-17-tahun-2014\", \"judul\": \"UU No. 17 Tahun 2014 tentang Majelis Permusyawaratan Rakyat, Dewan Perwakilan Rakyat, Dewan Perwakilan Daerah, dan Dewan Perwakilan Rakyat Daerah\", \"label\": \"UU No. 17 Tahun 2014\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/38763/uu-no-28-tahun-2009\", \"judul\": \"UU No. 28 Tahun 2009 tentang Pajak Daerah dan Retribusi Daerah\", \"label\": \"UU No. 28 Tahun 2009\"}], \"diubah_dengan\": [{\"url\": \"https://peraturan.bpk.go.id/Details/337869/uu-no-1-tahun-2026\", \"judul\": \"UU No. 1 Tahun 2026 tentang Penyesuaian Pidana\", \"label\": \"UU No. 1 Tahun 2026\", \"keterangan\": \"Ketentuan Pasal 238 dalam Undang-Undang Nomor 23 Tahun 2014, diubah\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/246523/uu-no-6-tahun-2023\", \"judul\": \"UU No. 6 Tahun 2023 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 2 Tahun 2022 tentang Cipta Kerja menjadi Undang-Undang\", \"label\": \"UU No. 6 Tahun 2023\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/149750/uu-no-11-tahun-2020\", \"judul\": \"UU No. 11 Tahun 2020 tentang Cipta Kerja\", \"label\": \"UU No. 11 Tahun 2020\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/135060/perpu-no-1-tahun-2020\", \"judul\": \"PERPU No. 1 Tahun 2020 tentang Kebijakan Keuangan Negara dan Stabilitas Sistem Keuangan untuk Penanganan Pandemi Corona Virus Disease 2019 (COVID-19) dan/atau dalam Rangka Menghadapi Ancaman yang Membahayakan Perekonomian Nasional dan/atau Stabilitas Sistem Keuangan\", \"label\": \"PERPU No. 1 Tahun 2020\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/38209/uu-no-9-tahun-2015\", \"judul\": \"UU No. 9 Tahun 2015 tentang Perubahan Kedua Atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah\", \"label\": \"UU No. 9 Tahun 2015\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/37678/uu-no-2-tahun-2015\", \"judul\": \"UU No. 2 Tahun 2015 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 2 Tahun 2014 tentang Perubahan atas Undang-Undang Nomor 23 Tahun 2014 Tentang Pemerintahan Daerah Menjadi Undang-Undang\", \"label\": \"UU No. 2 Tahun 2015\"}], \"dicabut_sebagian_dengan\": [{\"url\": \"https://peraturan.bpk.go.id/Details/195696/uu-no-1-tahun-2022\", \"judul\": \"UU No. 1 Tahun 2022 tentang Hubungan Keuangan antara Pemerintah Pusat dan Pemerintahan Daerah\", \"label\": \"UU No. 1 Tahun 2022\", \"keterangan\": \"Pasal 1 angka 30, Pasal 1 angka 38, Pasal L angka 47\\r\\nsampai dengan angka 49, Pasal 245 sepanjang terkait\\r\\ndengan Pajak Daerah dan Retribusi Daerah, Pasal\\r\\n279, Pasal 285 ayat (2) huruf a angka 1 sampai\\r\\ndengan angka 4, Pasal 288 sampai dengan Pasal 291,\\r\\nPasal 296, Pasal 302, Pasal 324, dan Pasal 325\\r\\nUndang-Undang Nomor 23 Tahun 2014 tentang\\r\\nPemerintahan Daerah (l,embaran Negara Republik\\r\\nIndonesia Tahun 2Ol4 Nomor 244, Tambahan\\r\\nLembaran Negara Republik Indonesia Nomor 5587)\\r\\nsebagaimana telah beberapa kali diubah, terakhir\\r\\ndengan Undang-Undang Nomor 11 Tahun 2020\\r\\ntentang Cipta Kerja (Lembaran Negara Republik\\r\\nIndonesia Tahun 2O2O Nomor 245, Tambahan\\r\\nLembaran Negara Republik Indonesia Nomor 6573);\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/122742/uu-no-17-tahun-2019\", \"judul\": \"UU No. 17 Tahun 2019 tentang Sumber Daya Air\", \"label\": \"UU No. 17 Tahun 2019\", \"keterangan\": \"Ketentuan mengenai pembagian urusan pemerintahan konkuren antara Pemerintah Pusat dan pemerintah daerah provinsi dan pemerintah daerah kabupaten/kota, Angka I Matriks pembagian urusan pemerintahan konkuren antara pemerintah pusat dan pemerintah daerah provinsi dan pemerintah daerah kabupaten/kota: (a). huruf C Pembagian Urusan Pemerintahan Bidang Pekerjaan Umum dan Penataan Ruang Nomor 1 Suburusan Sumber Daya Air (SDA) kolom 3 huruf b, kolom 4 huruf b, dan kolom 5 huruf b; (b). huruf CC Pembagian Urusan Pemerintahan Bidang Energi dan Sumber Daya Mineral Nomor I Sub-Urusan Geologi kolom 3 huruf a, kolom 4 huruf b, dan kolom 5, yang tertuang dalam lampiran yang merupakan bagian tidak terpisahkan dari Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah sebagaimana telah beberapa kali diubah terakhir dengan Undang-Undang Nomor 9 Tahun 2015 tentang Perubahan Kedua atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah\"}]}', 'Nasional', 'Otonomi Daerah', 'https://peraturan.bpk.go.id/Details/38685/uu-no-23-tahun-2014', 'normal', '2026-08-17 13:48:43', '2026-08-18 13:46:26'),
  (57, 'UU', '1', 2022, 'Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan antara Pemerintah Pusat dan Pemerintahan Daerah', 'berlaku', 'mencabut: 2 peraturan; mencabut sebagian: 2 peraturan', '{\"mencabut\": [{\"url\": \"https://peraturan.bpk.go.id/Details/38763/uu-no-28-tahun-2009\", \"judul\": \"UU No. 28 Tahun 2009 tentang Pajak Daerah dan Retribusi Daerah\", \"label\": \"UU No. 28 Tahun 2009\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/40770/uu-no-33-tahun-2004\", \"judul\": \"UU No. 33 Tahun 2004 tentang Perimbangan Keuangan antara Pemerintah Pusat dan Pemerintahan Daerah\", \"label\": \"UU No. 33 Tahun 2004\"}], \"mencabut_sebagian\": [{\"url\": \"https://peraturan.bpk.go.id/Details/149750/uu-no-11-tahun-2020\", \"judul\": \"UU No. 11 Tahun 2020 tentang Cipta Kerja\", \"label\": \"UU No. 11 Tahun 2020\", \"keterangan\": \"Pasal 114 dan Pasal 176 angka 4 ayat (4) dalam Pasal\\r\\n252 dan angka 7 Undang-Undang Nomor 11 Tahun\\r\\n2O2O tettang Cipta Kerja (Lembaran Negara Republik\\r\\nIndonesia Tahun 2O2O Nomor 245, Tambahan\\r\\nLembaran Negara Republik Indonesia Nomor 6573)\"}, {\"url\": \"https://peraturan.bpk.go.id/Details/38685/uu-no-23-tahun-2014\", \"judul\": \"UU No. 23 Tahun 2014 tentang Pemerintahan Daerah\", \"label\": \"UU No. 23 Tahun 2014\", \"keterangan\": \"Pasal 1 angka 30, Pasal 1 angka 38, Pasal L angka 47\\r\\nsampai dengan angka 49, Pasal 245 sepanjang terkait\\r\\ndengan Pajak Daerah dan Retribusi Daerah, Pasal\\r\\n279, Pasal 285 ayat (2) huruf a angka 1 sampai\\r\\ndengan angka 4, Pasal 288 sampai dengan Pasal 291,\\r\\nPasal 296, Pasal 302, Pasal 324, dan Pasal 325\\r\\nUndang-Undang Nomor 23 Tahun 2014 tentang\\r\\nPemerintahan Daerah (l,embaran Negara Republik\\r\\nIndonesia Tahun 2Ol4 Nomor 244, Tambahan\\r\\nLembaran Negara Republik Indonesia Nomor 5587)\\r\\nsebagaimana telah beberapa kali diubah, terakhir\\r\\ndengan Undang-Undang Nomor 11 Tahun 2020\\r\\ntentang Cipta Kerja (Lembaran Negara Republik\\r\\nIndonesia Tahun 2O2O Nomor 245, Tambahan\\r\\nLembaran Negara Republik Indonesia Nomor 6573);\"}]}', 'Nasional', 'Pajak Daerah', 'https://peraturan.bpk.go.id/Details/195696/uu-no-1-tahun-2022', 'normal', '2026-08-17 13:48:43', '2026-08-18 13:46:26'),
